Implemented `solution.py` with the required `parse_duration` function, strict token validation, case-sensitive unit handling, `ValueError` on invalid input, and truncation of milliseconds toward zero.

```python
def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    if s.endswith("ms"):
        number = s[:-2]
        is_milliseconds = True
        multiplier = None
    elif s.endswith("s"):
        number = s[:-1]
        is_milliseconds = False
        multiplier = 1
    elif s.endswith("m"):
        number = s[:-1]
        is_milliseconds = False
        multiplier = 60
    elif s.endswith("h"):
        number = s[:-1]
        is_milliseconds = False
        multiplier = 3600
    else:
        raise ValueError("invalid duration")

    if not number:
        raise ValueError("missing number")

    for ch in number:
        if ch < "0" or ch > "9":
            raise ValueError("invalid number")

    value = int(number)

    if is_milliseconds:
        return value // 1000

    return value * multiplier
```

```python
def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError

    if s.endswith("ms"):
        unit = "ms"
        number = s[:-2]
    elif s.endswith("s"):
        unit = "s"
        number = s[:-1]
    elif s.endswith("m"):
        unit = "m"
        number = s[:-1]
    elif s.endswith("h"):
        unit = "h"
        number = s[:-1]
    else:
        raise ValueError

    if not number:
        raise ValueError

    value = 0
    for ch in number:
        if ch < "0" or ch > "9":
            raise ValueError
        value = value * 10 + (ord(ch) - ord("0"))

    if unit == "ms":
        return value // 1000
    if unit == "s":
        return value
    if unit == "m":
        return value * 60
    return value * 3600
```

```python
def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("duration must be a string")
    if not s:
        raise ValueError("empty duration")

    i = 0
    n = len(s)
    while i < n and '0' <= s[i] <= '9':
        i += 1

    if i == 0 or i == n:
        raise ValueError("invalid duration")

    number_part = s[:i]
    suffix = s[i:]

    if suffix == "ms":
        return int(number_part) // 1000
    if suffix == "s":
        return int(number_part)
    if suffix == "m":
        return int(number_part) * 60
    if suffix == "h":
        return int(number_part) * 3600

    raise ValueError("invalid duration unit")
```

