```python
import re

_INT_RE = re.compile(r"-?[0-9]+(?:_[0-9]+)*")


def _is_cjk(ch: str) -> bool:
    cp = ord(ch)

    # Hangul
    if 0x1100 <= cp <= 0x11FF:
        return True
    if 0x3130 <= cp <= 0x318F:
        return True
    if 0xA960 <= cp <= 0xA97F:
        return True
    if 0xAC00 <= cp <= 0xD7AF:
        return True
    if 0xD7B0 <= cp <= 0xD7FF:
        return True

    # Hiragana / Katakana
    if 0x3041 <= cp <= 0x3096:
        return True
    if 0x3099 <= cp <= 0x309F:
        return True
    if 0x30A1 <= cp <= 0x30FA:
        return True
    if cp == 0x30FB:
        return False
    if 0x30FC <= cp <= 0x30FF:
        return True
    if 0x31F0 <= cp <= 0x31FF:
        return True
    if 0x1B000 <= cp <= 0x1B16F:
        return True

    # Halfwidth Katakana
    if 0xFF66 <= cp <= 0xFF9D:
        return True
    if cp in (0xFF9E, 0xFF9F):
        return True

    # Bopomofo
    if 0x3100 <= cp <= 0x312F:
        return True
    if 0x31A0 <= cp <= 0x31BF:
        return True

    # CJK radicals and ideographs
    if 0x2E80 <= cp <= 0x2EFF:
        return True
    if 0x2F00 <= cp <= 0x2FDF:
        return True
    if cp in (0x3005, 0x3006, 0x3007):
        return True
    if 0x3400 <= cp <= 0x4DBF:
        return True
    if 0x4E00 <= cp <= 0x9FFF:
        return True
    if 0xF900 <= cp <= 0xFAFF:
        return True
    if 0x20000 <= cp <= 0x2FA1F:
        return True
    if 0x30000 <= cp <= 0x323AF:
        return True

    return False


def slugify(s: str) -> str:
    out = []
    dash_pending = False

    for ch in s:
        if "A" <= ch <= "Z":
            ch = chr(ord(ch) + 32)

        if ("a" <= ch <= "z") or ("0" <= ch <= "9") or _is_cjk(ch):
            if dash_pending and out:
                out.append("-")
            out.append(ch)
            dash_pending = False
        else:
            dash_pending = True

    if not out:
        return "-"

    return "".join(out)


def safe_int(value, default=None):
    if isinstance(value, bool):
        return value

    if isinstance(value, int):
        return value

    if isinstance(value, str):
        stripped = value.strip()
        if _INT_RE.fullmatch(stripped):
            try:
                return int(stripped.replace("_", ""))
            except (TypeError, ValueError):
                return default
        return default

    return default
```
